import json
import os
import httpx
request_data = {
"model": "kimi-k3.1-pro",
"messages": [
{"role": "user", "content": "你好，请介绍一下流式输出。"},
],
"stream": True,
"stream_options": {"include_usage": True},
}
headers = {
"Authorization": f"Bearer {os.environ['MOONSHOT_API_KEY']}",
}
usage = None
# 使用 httpx.stream 在数据到达时逐行读取 SSE 响应，避免等待整个响应缓冲完成
with httpx.stream(
"POST",
"https://api.moonshot.cn/v1/chat/completions",
headers=headers,
json=request_data,
) as response:
response.raise_for_status()
for line in response.iter_lines():
if not line.startswith("data:"):
continue
payload = line[5:].lstrip()
if payload == "[DONE]":
break
chunk = json.loads(payload)
choices = chunk.get("choices", [])
chunk_usage = chunk.get("usage")
if chunk_usage is None and choices:
chunk_usage = choices[0].get("usage")
if chunk_usage:
usage = chunk_usage
if not choices:
continue
choice = choices[0]
delta = choice["delta"]
role = delta.get("role")
if role:
print("role:", role)
content = delta.get("content")
if content:
print(content, end="")
if usage:
print("\ntotal_tokens:", usage["total_tokens"])
const axios = require("axios");
const requestData = {
model: "kimi-k3.1-pro",
messages: [
{ role: "user", content: "你好，请介绍一下流式输出。" },
],
stream: true,
stream_options: { include_usage: true },
};
axios.post("https://api.moonshot.cn/v1/chat/completions", requestData, {
headers: {
"Authorization": `Bearer ${process.env.MOONSHOT_API_KEY}`,
},
responseType: "stream",
}).then((response) => {
let buffer = "";
let usage;
response.data.on("data", (rawChunk) => {
buffer += rawChunk.toString();
const events = buffer.split(/\r?\n\r?\n/);
buffer = events.pop() ?? "";
for (const event of events) {
const dataLines = event
.split(/\r?\n/)
.filter((line) => line.startsWith("data:"))
.map((line) => line.slice(5).trimStart());
if (dataLines.length === 0) continue;
const payload = dataLines.join("\n");
if (payload === "[DONE]") {
if (usage) console.log("\ntotal_tokens:", usage.total_tokens);
response.data.destroy();
return;
}
const chunk = JSON.parse(payload);
const choices = chunk.choices || [];
const chunkUsage = chunk.usage ?? choices[0]?.usage;
if (chunkUsage) usage = chunkUsage;
if (choices.length === 0) {
continue;
}
const delta = choices[0].delta;
if (delta.role) {
console.log("role:", delta.role);
}
if (delta.content) {
process.stdout.write(delta.content);
}
}
});
}).catch((error) => {
console.error("Error in request:", error);
});
